// Read-only public snapshot. Every query and attachment is served by this origin.
const mirrorCache=new Map();
function mirrorRead(name){if(!mirrorCache.has(name))mirrorCache.set(name,fetchReady('/zcst-admissions-query/public-data/'+name+'.json').then(r=>{if(!r.ok)throw Error('数据加载失败，请重试');return r.json()}).catch(e=>{mirrorCache.delete(name);throw e}));return mirrorCache.get(name)}
const mirrorNorm=s=>String(s||'').normalize('NFKC').replace(/\s/g,'').toLowerCase();
async function mirrorRequest(path,options={}){
 try{
 if(options.method&&options.method!=='GET')throw Error('备用入口只提供查询，请到原站管理数据');
 const d=await mirrorRead('index'),v=d.meta.version,u=new URL(path,'https://local.invalid'),p=u.searchParams;
 const start=Number(p.get('start')||v.default_start),end=Number(p.get('end')||v.default_end),major=p.get('major')||'';
 const count=s=>Object.entries(s.years).reduce((n,[y,k])=>n+(+y>=start&&+y<=end?k:0),0);
 let result;
 if(u.pathname==='/api/meta')result=d.meta;
 else if(u.pathname==='/api/schools'){
 const q=mirrorNorm(p.get('q'));result={schools:d.schools.filter(s=>s.terms.some(t=>t.includes(q))).sort((a,b)=>(mirrorNorm(b.name)===q)-(mirrorNorm(a.name)===q)||b.total-a.total||a.name.localeCompare(b.name,'zh')).slice(0,30).map(s=>({...s,terms:undefined,years:undefined,period_total:count(s)}))};
 }else if(u.pathname==='/api/regions'){
 const city=p.get('city')||null,regions=d.cities.map(city=>{const ss=d.schools.filter(s=>s.city===city),annual=[];for(let year=start;year<=end;year++){const coverage=v.years.find(y=>y.year===year);annual.push({year,count:coverage?ss.reduce((n,s)=>n+(s.years[year]||0),0):null,status:coverage?(coverage.complete?'完整名单':'部分名单'):'数据未导入'})}return{city,total:ss.reduce((n,s)=>n+count(s),0),schools:ss.filter(s=>count(s)>0).length,annual}}).sort((a,b)=>b.total-a.total||d.cities.indexOf(a.city)-d.cities.indexOf(b.city));
 result={version:v.id,start,end,city,total:regions.reduce((n,r)=>n+r.total,0),regions,schools:city?d.schools.filter(s=>s.city===city&&count(s)>0).map(s=>({...s,terms:undefined,years:undefined,period_total:count(s)})).sort((a,b)=>b.period_total-a.period_total||a.name.localeCompare(b.name,'zh')):[]};
 }else{
 const match=u.pathname.match(/^\/api\/schools\/([a-f0-9]+)\/(summary|students|export)$/);if(!match)throw Error('此入口只支持公开查询');
 const school=await mirrorRead(match[1]);if(p.has('version')&&Number(p.get('version'))!==v.id)throw Error('数据版本已更新，请刷新页面');
 const rows=school.rows.filter(r=>r.year>=start&&r.year<=end&&(!major||r.major===major));
 if(match[2]==='students'){const page=Math.max(1,Number(p.get('page')||1));result={total:rows.length,page,size:50,rows:rows.slice((page-1)*50,page*50)}}
 else{
 const annual=[];for(let year=start;year<=end;year++){const coverage=v.years.find(y=>y.year===year),groups=new Map();for(const r of rows)if(r.year===year)groups.set(r.major,(groups.get(r.major)||0)+1);annual.push({year,count:coverage?rows.filter(r=>r.year===year).length:null,status:coverage?(coverage.complete?'完整名单':'部分名单'):'数据未导入',majors:[...groups].map(([major,count])=>({year,major,count})).sort((a,b)=>b.count-a.count||a.major.localeCompare(b.major,'zh'))})}
 const summary={...school.summary,start,end,major,total:rows.length,annual,majors:[...new Set(school.rows.filter(r=>r.year>=start&&r.year<=end).map(r=>r.major))].sort()};
 summary.report=`据当前导入明细，${start}—${end}级，${summary.school.name}共有${rows.length}名学生被我校录取，各年分别为`+annual.map(y=>y.year+'级'+(y.count===null?'数据未导入':y.count+'人')).join('、')+'。';
 result=match[2]==='export'?{summary,students:rows,filename:summary.school.name+'_'+start+'-'+end+'录取情况.xlsx'}:summary;
 }
 }
 return new Response(JSON.stringify(result),{headers:{'Content-Type':'application/json;charset=utf-8'}});
 }catch(e){return new Response(JSON.stringify({detail:e.message}),{status:400,headers:{'Content-Type':'application/json'}})}
}

