async function scoreData(name){if(!scoreFiles[name])scoreFiles[name]=fetch('/zcst-admissions-query/scores/'+name+'.json').then(r=>{if(!r.ok)throw Error('分数数据暂时无法加载');return r.json();}).catch(e=>{delete scoreFiles[name];throw e;});return scoreFiles[name];}
function moduleNav(active){const items=[['outside','普高省外分数'],['colleges','学院介绍'],['policies','招生政策'],['transfer-plan','2027专升本拟招生专业'],['college-contacts','学院联系电话'],['inside','普高省内分数'],['catalog','专业介绍'],['schools','生源中学'],['transfer-score','2026年专升本录取分数'],['department-contacts','行政职能部门联系电话']];const labels={outside:'普高<br>省外分数',inside:'普高<br>省内分数','college-contacts':'学院<br>联系电话','department-contacts':'行政职能<span class="nav-mobile-break"></span>部门<br>联系电话','transfer-plan':'<span class="nav-year">2027专升本</span>拟招生专业','transfer-score':'<span class="nav-year">2026专升本</span>录取分数'};document.querySelector('#module-nav').innerHTML=items.map(([id,label])=>`<button data-module="${id}" class="${active===id?'active':''} ${id==='schools'?'school-entry':id==='policies'?'policy-entry':['outside','inside'].includes(id)?'nav-score':['colleges','catalog'].includes(id)?'nav-intro':'nav-contact'}" aria-label="${label}" aria-current="${active===id?'page':'false'}">${labels[id]||label}</button>`).join('');}
async function showHome(){if(typeof Transfer!=='undefined')Transfer.clearLink();ScoreState.query='';ScoreState.province='';ScoreState.major='';ScoreState.year=2026;document.activeElement?.blur();await openModule('outside');window.scrollTo(0,0);}
async function openModule(kind){ScoreState.module=kind;const seq=++ScoreState.sequence;searchSeq++;moduleNav(kind);if(kind==='home'){await showHome();return;}$('#app').innerHTML='<p class="loading">正在加载…</p>';try{if(kind==='transfer-plan'||kind==='transfer-score'){await Transfer.open(kind);return;}if(kind==='policies'){await showPolicies();return;}if(kind==='colleges'){await showColleges();return;}if(kind==='college-contacts'){await showCollegeContacts();return;}if(kind==='department-contacts'){await showDepartmentContacts();return;}if(kind==='catalog'){CatalogState.origin='catalog';await drawCatalog();return;}if(kind==='schools'){await refreshMeta();if(seq!==ScoreState.sequence)return;await showQuery();}else{await Promise.all([scoreData('national'),...(kind==='inside'?[scoreData('guangdong'),scoreData('hmt')]:[])]);if(seq!==ScoreState.sequence)return;drawScores();}}catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<div class="empty"><p>${esc(e.message)}</p><button class="btn" data-module="${kind}">重新加载</button></div>`;}}
const scoreValue=v=>v===null||v===undefined||v===''?'暂无数据':typeof v==='number'?String(v):esc(v);
function metricClass(label){return {'最高分':'metric-high','最低分':'metric-low','最低排位':'metric-rank'}[label]||'';}
function scoreMetric(label,value){return `<div class="${metricClass(label)}"><span>${label}</span><strong>${scoreValue(value)}</strong></div>`;}
function provinceCard(r){return `<article class="score-card"><h3>${esc(r.category)}</h3><div class="score-all">${[['最低分',r.min],['最高分',r.max],['最低排位',r.rank],['最高排位','未提供'],['录取人数','未提供'],['省控线',r.line],['超省控线',r.over]].map(([k,v])=>scoreMetric(k,v)).join('')}</div></article>`;}
function specialCount(aux,label='过特控线人数'){return aux?`<div class="special-count"><span>${label}</span><strong>${scoreValue(aux.value)}${typeof aux.value==='number'?'<small>人</small>':''}</strong></div>`:'';}
function majorCard(r,overview,withIntro=true){const lines=[...new Set(overview.map(x=>x.line).filter(x=>typeof x==='number'))];const line=lines.length===1?lines[0]:null;return `<article class="score-card"><h3>${esc(r.name)} <small>${r.code}</small></h3><div class="score-all">${[['最低分',r.min],['最高分',r.max],['最低排位',r.worst],['最高排位',r.best],['录取人数',r.count],['平均分',r.avg.toFixed(1)],['省控线',line],['超省控线',line===null?null:r.min-line]].map(([k,v])=>scoreMetric(k,v)).join('')}</div>${withIntro?`<button class="major-info-link" data-major-name="${esc(r.name)}">专业介绍 / 创新班 ›</button>`:''}</article>`;}

function drawScores(){const z=ScoreState;$('#app').innerHTML=`<button class="back-nav" data-module="home">← 返回首页</button><div class="score-title"><h1>${z.module==='inside'?(z.category==='港澳台'?'华侨港澳台联招':'普高省内分数 · 广东'):'普高省外分数'}</h1><label>年份 <select id="score-year" aria-label="录取年份"><option ${z.year===2026?'selected':''}>2026</option><option ${z.year===2025?'selected':''}>2025</option></select></label></div>${z.module==='inside'?`<div class="score-tabs">${['物理','历史','港澳台'].map(c=>`<button class="btn ${z.category===c?'primary':'soft'}" data-score-category="${c}">${c==='港澳台'?'港澳台联招':c+'类'}</button>`).join('')}</div><div id="score-overview"></div><label class="score-search-label" ${z.category==='港澳台'?'hidden':''} for="major-query">查询专业</label><input class="score-search" ${z.category==='港澳台'?'hidden':''} id="major-query" aria-label="专业名称或代码" placeholder="输入专业名称或代码，如计算机、311" value="${esc(z.major)}"><div id="score-results"></div>`:`<input class="score-search" id="province-query" aria-label="省份名称" placeholder="输入省份，如湖南、内蒙古" value="${esc(z.query)}"><div id="province-options" class="province-options"></div><div id="score-results"></div>`}`;renderScoreResults().catch(e=>{if($('#score-results'))$('#score-results').innerHTML=`<p class="empty">${esc(e.message)}<button class="btn" data-module="${ScoreState.module}">重新加载</button></p>`;});}
function planMarkup(data,province,year){
 const rows=data.records.filter(r=>r.year===year&&r.province===province);
 if(!rows.length)return `<p class="score-count">暂无${year}年招生计划</p>`;
 return `<section class="province-plan"><header><h3>${year}年招生计划 <b>${rows.reduce((n,r)=>n+r.total,0)}</b> 人</h3><a href="${esc(data.source.image)}" target="_blank" rel="noopener">计划原表 ↗</a></header>${rows.map(r=>`${rows.length>1?`<h4>${esc(r.group)} · ${r.total}人</h4>`:''}<div class="province-plan-grid">${r.items.map(x=>`<div><span>${esc(x.category==='普通类'?'普通类 · '+x.subject:x.category+(x.subject?' · '+x.subject:''))}</span><b>${x.count}<small>人</small></b></div>`).join('')}</div>`).join('')}<small class="plan-caption">招生计划与实际录取人数分别统计</small></section>`;
}
let scoreRenderId=0;
async function renderScoreResults(){
 const ticket=++scoreRenderId,z=ScoreState,seq=z.sequence,n=await scoreData('national');
 const current=()=>ticket===scoreRenderId&&seq===z.sequence&&$('#score-results');
 if(!current())return;
 const records=n.records.filter(r=>r.year===z.year);
 if(z.module==='inside'){
  if(z.category==='港澳台'){
   const h=await scoreData('hmt');if(!current()||z.category!=='港澳台')return;
   $('#score-overview').innerHTML='';
   $('#score-results').innerHTML=z.year!==h.year?'<p class="empty">暂无'+z.year+'年华侨港澳台联招数据</p>':`<p class="score-count">${h.year}年 · 华侨港澳台联招 · 合计${h.records.reduce((t,r)=>t+r.count,0)}人</p><div class="major-score-grid">${h.records.map(r=>`<article class="score-card"><h3>${esc(r.category)}</h3><div class="score-all">${[['最低分',r.min],['最高分',r.max],['最低排位',r.worst],['最高排位',r.best],['录取人数',r.count]].map(([k,v])=>scoreMetric(k,v)).join('')}</div></article>`).join('')}</div>`;
   return;
  }
  const overview=records.filter(r=>r.province==='广东'&&(z.category==='历史'?r.category==='历史':r.category.startsWith('物理')));
  $('#score-overview').innerHTML='<div class="score-section-heading"><h3 class="score-subtitle">'+z.year+'年省级概况</h3>'+specialCount(n.auxiliary.find(x=>x.year===z.year&&x.province==='广东'),'全省过特控线人数')+'</div>'+overview.map(provinceCard).join('');
  $('#score-overview').setAttribute('data-count',overview.length);
  const g=await scoreData('guangdong');if(!current())return;
  const rows=g.records.filter(r=>r.year===z.year&&r.category===z.category&&(r.name.includes(z.major.trim())||r.code.includes(z.major.trim())));
  $('#score-results').innerHTML=z.year!==2026?'<p class="empty">暂无2025年专业明细</p>':`<p class="score-count">2026年 · ${z.category}类 · ${rows.length}个专业</p><div class="major-score-grid gd-major-grid">${rows.map(r=>majorCard(r,overview)).join('')||'<p class="empty">未找到匹配专业</p>'}</div>`;return;
 }
 let plans=null;
 try{plans=await scoreData('plans');}catch(e){/* Existing score queries remain usable if plans fail. */}
 if(!current())return;
 const normalize=s=>s.replace(/\s|省|自治区|壮族|回族|维吾尔|市/g,'');
 const query=normalize(z.query),provinces=[...new Set([...records.map(r=>r.province),...(plans?.records||[]).filter(r=>r.year===z.year).map(r=>r.province)])];
 const matches=provinces.filter(p=>normalize(p).includes(query));
 $('#province-options').innerHTML=matches.map(p=>`<button class="btn ${z.province===p?'primary':'soft'}" data-score-province="${p}">${p==='广东'?'广东 · 普高省内分数':p}</button>`).join('');
 if(query&&!matches.length){$('#score-results').innerHTML='<p class="empty">暂无上传数据</p>';return;}
 const exact=matches.find(p=>normalize(p)===query),selected=exact||z.province;
 if(selected==='广东'){$('#score-results').innerHTML='<button class="btn primary" data-module="inside">进入普高省内分数</button>';return;}
 if(!selected||!matches.includes(selected)){$('#score-results').innerHTML='';return;}
 const aux=n.auxiliary.find(x=>x.year===z.year&&x.province===selected),rows=records.filter(r=>r.province===selected);
 $('#score-results').innerHTML=`<div class="score-section-heading"><h2 class="score-subtitle">${selected} · ${z.year}年</h2>${specialCount(aux)}</div>`+
 (plans?planMarkup(plans,selected,z.year):'<p class="score-count">招生计划暂时未加载 <button class="btn soft" data-plan-retry>重试</button></p>')+
 (rows.length?`<div class="province-score-grid" data-count="${rows.length}">${rows.map(provinceCard).join('')}</div>`:`<p class="empty">暂无${z.year}年${selected}录取分数</p>`);
}
document.addEventListener('click',e=>{if(e.target.closest('[data-plan-retry]'))renderScoreResults();});
document.addEventListener('click',e=>{const m=e.target.closest('[data-module]');if(m){e.preventDefault();if(typeof Transfer!=='undefined')Transfer.clearLink();openModule(m.dataset.module);return;}const c=e.target.closest('[data-score-category]');if(c){ScoreState.category=c.dataset.scoreCategory;drawScores();}const p=e.target.closest('[data-score-province]');if(p){ScoreState.province=p.dataset.scoreProvince;ScoreState.query=p.dataset.scoreProvince;if(p.dataset.scoreProvince==='广东')openModule('inside');else drawScores();}});
document.addEventListener('input',e=>{if(e.target.id==='province-query'){ScoreState.query=e.target.value;ScoreState.province='';renderScoreResults();}if(e.target.id==='major-query'){ScoreState.major=e.target.value;renderScoreResults();}});
document.addEventListener('change',e=>{if(e.target.id==='score-year'){ScoreState.year=Number(e.target.value);drawScores();}});

const CatalogState={query:'',college:'',onlyClasses:false,detail:'',origin:'catalog',page:1,microQuery:''};
let catalogPromise;
let microPromise;
async function microData(){if(!microPromise)microPromise=fetchReady('/zcst-admissions-query/catalog/micro.json?v=20261031-micro').then(r=>{if(!r.ok)throw Error('微专业资料暂时无法加载');return r.json();}).catch(e=>{microPromise=null;throw e;});return microPromise;}
function catalogTabs(active){return `<nav class="catalog-tabs" aria-label="专业分类">${[['undergraduate',71,'本科专业'],['innovation',28,'创新特色班'],['micro',20,'微专业']].map(([id,n,label])=>`<button data-catalog-section="${id}" class="${id===active?'active':''}" aria-pressed="${id===active}" aria-label="${n}个${label}"><b>${n}</b><span>个${label}</span></button>`).join('')}</nav>`;}
const microDate=s=>s?s.replace(/-/g,'.'):'即日起';
function microMatches(m,q){return [m.name,m.college].join(' ').toLowerCase().includes(q.trim().toLowerCase());}
async function showMicro(id=''){
 ScoreState.module='catalog';const seq=++ScoreState.sequence;searchSeq++;moduleNav('catalog');CatalogState.detail='micro';
 $('#app').innerHTML='<p class="loading">正在加载微专业…</p>';
 try{
  const data=await microData();if(seq!==ScoreState.sequence)return;
  if(id){
   const m=data.records.find(x=>x.id===id);if(!m)throw Error('未找到微专业');
   $('#app').innerHTML=`<div class="catalog-back"><button class="back-nav" data-catalog-section="micro">← 返回微专业</button><button class="back-nav" data-module="home">返回首页</button></div><header class="major-heading"><small>微专业 · ${data.year}年${esc(data.term)}</small><h1>${esc(m.name)}</h1></header><article class="micro-detail"><dl><div><dt>开设单位</dt><dd>${esc(m.college)}</dd></div><div><dt>报名时间</dt><dd>${microDate(m.start)} — ${microDate(m.end)}</dd></div></dl><p class="score-count">这是2026年秋季公布批次，后续招生安排以学校通知为准。</p><div class="innovation-links"><a class="btn soft" href="${esc(data.source.url)}" target="_blank" rel="noopener">学校微专业推文 ↗</a><a class="btn soft" href="${esc(data.source.image)}" target="_blank" rel="noopener">原始统计表 ↗</a></div></article>`;
  }else{
   $('#app').innerHTML=`${moduleBack()}<div class="score-title"><h1>专业介绍</h1></div>${catalogTabs('micro')}<div class="micro-heading"><h2>${data.year}年${esc(data.term)}</h2><a href="${esc(data.source.url)}" target="_blank" rel="noopener">学校推文 ↗</a></div><input class="score-search" id="micro-query" aria-label="搜索微专业或开设单位" placeholder="输入微专业名称或开设单位" value="${esc(CatalogState.microQuery)}"><div id="micro-results"></div>`;
   renderMicro(data);
  }
  window.scrollTo(0,0);
 }catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<div class="empty">${esc(e.message)}<button class="btn" data-catalog-section="micro">重新加载</button><button class="btn" data-module="catalog">返回专业介绍</button></div>`;}
}
function renderMicro(data){const rows=data.records.filter(m=>microMatches(m,CatalogState.microQuery));$('#micro-results').innerHTML=`<p class="score-count">共${rows.length}个微专业 · 点击查看报名时间</p><div class="micro-grid">${rows.map(m=>`<button class="catalog-card micro-card" data-micro-id="${esc(m.id)}"><b>${esc(m.name)}</b><small>${esc(m.college)}</small><span class="catalog-open">查看详情 ›</span></button>`).join('')||'<p class="empty">未找到匹配微专业</p>'}</div>`;}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-catalog-section]');if(tab){const section=tab.dataset.catalogSection;if(section==='micro')showMicro();else if(section==='innovation')showInnovation();else openModule('catalog');return;}const m=e.target.closest('[data-micro-id]');if(m)showMicro(m.dataset.microId);});
document.addEventListener('input',async e=>{if(e.target.id!=='micro-query')return;CatalogState.microQuery=e.target.value;const seq=ScoreState.sequence;try{const data=await microData();if(seq===ScoreState.sequence&&$('#micro-results'))renderMicro(data);}catch(e){/* Retry is handled by the module entry. */}});
async function catalogData(){if(!catalogPromise)catalogPromise=fetchReady('/zcst-admissions-query/catalog/majors.json?v=20261031-spacing').then(r=>{if(!r.ok)throw Error('专业资料暂时无法加载');return r.json();}).catch(e=>{catalogPromise=null;throw e;});return catalogPromise;}
function catalogMatches(m,q){const word=q.trim().toLowerCase();return !word||[m.name,m.college,m.additionalClassNote||'',...m.classes,...(m.codes||[])].some(s=>s.toLowerCase().includes(word));}
async function drawCatalog(){const seq=ScoreState.sequence;const [data,scores]=await Promise.all([catalogData(),scoreData('guangdong')]);if(seq!==ScoreState.sequence)return;data.majors.forEach(m=>m.codes=scores.records.filter(r=>r.name===m.name).map(r=>r.code));CatalogState.detail='';$('#app').innerHTML=`<button class="back-nav" data-module="home">← 返回首页</button><div class="score-title"><h1>专业介绍</h1></div>${catalogTabs('undergraduate')}<input class="score-search" id="catalog-query" aria-label="搜索专业或创新班" placeholder="输入专业、代码或创新班名称" value="${esc(CatalogState.query)}"><div class="catalog-filters"><select id="catalog-college" aria-label="学院"><option value="">全部学院</option>${[...new Set(data.majors.map(m=>m.college))].map(c=>`<option ${c===CatalogState.college?'selected':''}>${esc(c)}</option>`).join('')}</select><label><input type="checkbox" id="catalog-classes" ${CatalogState.onlyClasses?'checked':''}>有创新班</label><button class="btn soft" data-brochure="1">完整简章</button></div><div id="catalog-results"></div>`;renderCatalogResults(data);}
function renderCatalogResults(data){const rows=data.majors.filter(m=>catalogMatches(m,CatalogState.query)&&(!CatalogState.college||m.college===CatalogState.college)&&(!CatalogState.onlyClasses||m.classes.length||m.additionalClassNote));$('#catalog-results').innerHTML=`<p class="score-count">共${rows.length}个专业</p><div class="catalog-grid">${rows.map(m=>`<button class="catalog-card" data-major-name="${esc(m.name)}"><b>${esc(m.name)}</b><small>${esc(m.college)}</small>${m.classes.length?`<span class="class-tag">${m.classes.length}个特色班</span>`:m.additionalClassNote?'<span class="class-tag">创新班介绍</span>':''}<span class="catalog-open">分数 · 介绍 ›</span></button>`).join('')||'<p class="empty">未找到匹配专业</p>'}</div>`;}
async function showMajor(name){const from=ScoreState.module;ScoreState.module='catalog';const seq=++ScoreState.sequence;searchSeq++;moduleNav('catalog');if(from!=='catalog')CatalogState.origin=from;CatalogState.detail=name;$('#app').innerHTML='<p class="loading">正在加载专业资料…</p>';try{const [data,g,n]=await Promise.all([catalogData(),scoreData('guangdong'),scoreData('national')]);if(seq!==ScoreState.sequence)return;const m=data.majors.find(x=>x.name===name);if(!m)throw Error('未找到对应专业');const rows=g.records.filter(r=>r.year===2026&&r.name===name);$('#app').innerHTML=`<div class="catalog-back"><button class="back-nav" data-catalog-back>← 返回${CatalogState.origin==='inside'?'普高省内分数':CatalogState.origin==='innovation'?'创新班目录':CatalogState.origin==='colleges'?'学院介绍':'专业列表'}</button><button class="back-nav" data-module="home">返回首页</button></div><header class="major-heading"><small>${esc(m.college)}</small><h1>${esc(m.name)}${m.track?`<small>（${esc(m.track)}）</small>`:''}</h1>${m.duration?`<small>学制：${esc(m.duration)}</small>`:''}</header><h2 class="score-subtitle">2026年广东录取分数</h2><div class="major-score-grid catalog-scores">${rows.map(r=>`<section><h3 class="score-subtitle">${esc(r.category)}类</h3>${majorCard(r,n.records.filter(v=>v.year===2026&&v.province==='广东'&&v.category.startsWith(r.category)),false)}</section>`).join('')||'<p class="empty">暂无上传的2026年该专业录取分数</p>'}</div>${m.classes.length||m.additionalClassNote?`<section class="major-innovation"><h2>创新班 / 特色班</h2>${m.classes.length?`<p class="innovation-source"><a href="${esc(data.innovation.article)}" target="_blank" rel="noopener">学校28个特色班推文 ↗</a></p><div class="class-tags">${m.classes.map(c=>`<strong class="class-tag">${esc(c)}</strong>`).join('')}</div><details><summary>查看培养内容与选拔方式</summary><p>${esc(m.innovationText)}</p></details>`:m.additionalClassNote?`<p>${esc(m.additionalClassNote)}</p>`:''}</section>`:''}<div class="major-sections">${m.sections.filter(s=>s.title!=='特色班情况'&&s.title!=='2025年广东录取分数').map((s,i)=>`<details ${i===0?'open':''}><summary>${esc(s.title)}</summary><p>${esc(s.text)}</p></details>`).join('')}</div><div class="major-source"><b>${esc(m.source.title)}</b>${m.pages.length?`<div class="source-page-links">${m.pages.map(p=>`<button class="btn soft" data-brochure="${p}">原文第${p}页</button>`).join('')}</div><small>电子页码；简章原页中的分数为2025年。</small>`:`<a href="${esc(m.source.url)}" target="_blank" rel="noopener">查看学校官网原文 ↗</a>`}</div>`;window.scrollTo(0,0);}catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<div class="empty">${esc(e.message)}<button class="btn" data-major-name="${esc(name)}">重试</button><button class="btn" data-module="catalog">返回专业列表</button></div>`;}}
function drawBrochure(page){page=Math.max(1,Math.min(80,Number(page)||1));CatalogState.page=page;ScoreState.module='catalog';++ScoreState.sequence;searchSeq++;moduleNav('catalog');const file='/zcst-admissions-query/catalog/pages/'+String(page).padStart(2,'0')+'.webp';$('#app').innerHTML=`<div class="catalog-back"><button class="back-nav" data-catalog-source-back>← 返回${CatalogState.detail?'专业详情':'专业列表'}</button><button class="back-nav" data-module="home">返回首页</button></div><div class="brochure-controls"><button class="btn soft" data-brochure="${page-1}" ${page===1?'disabled':''}>上一页</button><label>第 <select id="brochure-page" aria-label="简章页码">${Array.from({length:80},(_,i)=>`<option ${i+1===page?'selected':''}>${i+1}</option>`).join('')}</select> / 80页</label><button class="btn soft" data-brochure="${page+1}" ${page===80?'disabled':''}>下一页</button></div><p class="score-count">2026年招生简章 · 可放大查看原文</p><a href="${file}" target="_blank" rel="noopener"><img class="brochure-page" src="${file}" alt="2026年招生简章第${page}页"></a>`;window.scrollTo(0,0);}
document.addEventListener('click',e=>{if(e.target.closest('[data-college-contacts]')){showCollegeContacts();return;}const major=e.target.closest('[data-major-name]');if(major){if(ScoreState.module==='catalog'&&!CatalogState.detail)CatalogState.origin='catalog';showMajor(major.dataset.majorName);return;}const page=e.target.closest('[data-brochure]');if(page){drawBrochure(page.dataset.brochure);return;}if(e.target.closest('[data-catalog-source-back]')){if(CatalogState.detail)showMajor(CatalogState.detail);else openModule('catalog');return;}if(e.target.closest('[data-catalog-back]')){const origin=CatalogState.origin;CatalogState.detail='';if(origin==='innovation')showInnovation();else if(origin==='colleges')showColleges(CollegeState.selected);else openModule(origin==='inside'?'inside':'catalog');}});
document.addEventListener('input',async e=>{if(e.target.id!=='catalog-query')return;CatalogState.query=e.target.value;const seq=ScoreState.sequence;const data=await catalogData();if(seq===ScoreState.sequence&&$('#catalog-results'))renderCatalogResults(data);});
document.addEventListener('change',async e=>{if(e.target.id==='brochure-page'){drawBrochure(e.target.value);return;}if(!['catalog-college','catalog-classes'].includes(e.target.id))return;if(e.target.id==='catalog-college')CatalogState.college=e.target.value;else CatalogState.onlyClasses=e.target.checked;const seq=ScoreState.sequence,data=await catalogData();if(seq===ScoreState.sequence&&$('#catalog-results'))renderCatalogResults(data);});

function contactPhonesMarkup(phones,name=''){
 const sharedLocation=phones.length>1&&phones.every(p=>p.location&&p.location===phones[0].location)?phones[0].location:'';
 return `<div class="college-phones">${phones.map(p=>`<a class="college-phone" href="tel:${esc(p.number.replace(/-/g,''))}" aria-label="${esc([name,p.label,p.number].filter(Boolean).join(' '))}"><small>${esc(p.label)}</small><b>${esc(p.number)}</b>${p.location&&!sharedLocation?`<span>${esc(p.location)}</span>`:''}</a>`).join('')}</div>${sharedLocation?`<p class="contact-location">${esc(sharedLocation)}</p>`:''}`;
}
function collegeContactMarkup(data,name,directory=false){const c=(data.colleges||{})[name];if(!c)return '';return `<section class="college-contact"><header><strong>${directory?esc(name):'学院联系'}</strong><a href="${esc(c.source)}" target="_blank" rel="noopener">学院官网 ↗</a></header>${contactPhonesMarkup(c.phones,name)}</section>`;}

async function showCollegeContacts(){ScoreState.module='college-contacts';const seq=++ScoreState.sequence;searchSeq++;CatalogState.detail='';CatalogState.origin='catalog';moduleNav('college-contacts');$('#app').innerHTML='<p class="loading">正在加载学院电话…</p>';try{const data=await catalogData();if(seq!==ScoreState.sequence)return;$('#app').innerHTML=`<div class="catalog-back"><button class="back-nav" data-module="catalog">← 返回专业列表</button><button class="back-nav" data-module="home">返回首页</button></div><div class="score-title"><h1>学院联系电话</h1><span class="score-count">点击号码拨打</span></div><div class="college-directory">${Object.keys(data.colleges||{}).map(c=>collegeContactMarkup(data,c,true)).join('')}</div>`;window.scrollTo(0,0);}catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<div class="empty">${esc(e.message)}<button class="btn" data-college-contacts>重新加载</button><button class="btn" data-module="catalog">返回专业列表</button></div>`;}}
