async function showColleges(name=''){ScoreState.module='colleges';const seq=++ScoreState.sequence;searchSeq++;moduleNav('colleges');CollegeState.selected=name;$('#app').innerHTML='<p class="loading">正在加载学院介绍…</p>';try{const data=await catalogData();if(seq!==ScoreState.sequence)return;const profiles=data.profiles||{};if(name){const p=profiles[name];if(!p)throw Error('未找到学院');const majors=data.majors.filter(m=>m.college===name);$('#app').innerHTML=`<div class="catalog-back"><button class="back-nav" data-module="colleges">← 返回学院列表</button><button class="back-nav" data-module="home">返回首页</button></div><h1 class="portal-title">${esc(name)}</h1><section class="college-profile"><p>${esc(p.summary)}</p><a href="${esc(p.source)}" target="_blank" rel="noopener">学院官网完整介绍 ↗</a></section>${collegeContactMarkup(data,name)}${majors.length?`<h2 class="score-subtitle">专业介绍</h2><div class="catalog-grid">${majors.map(m=>`<button class="catalog-card" data-major-name="${esc(m.name)}"><b>${esc(m.name)}</b><span class="catalog-open">分数 · 专业 · 创新班 ›</span></button>`).join('')}</div>`:''}`;}else{$('#app').innerHTML=`${moduleBack()}<div class="score-title"><h1>学院介绍</h1><span class="score-count">18个学院</span></div><div class="college-profile-grid">${Object.values(profiles).map(p=>`<button class="catalog-card" data-college-profile="${esc(p.name)}"><b>${esc(p.name)}</b><small>${data.majors.filter(m=>m.college===p.name).map(m=>m.name).slice(0,3).join(' · ')||'教学与教育服务'}</small><span class="catalog-open">简介 · 专业 · 联系电话 ›</span></button>`).join('')}</div>`;}window.scrollTo(0,0);}catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<p class="empty">${esc(e.message)}<button class="btn" data-module="colleges">重新加载</button></p>`;}}
async function showDepartmentContacts(){ScoreState.module='department-contacts';const seq=++ScoreState.sequence;searchSeq++;moduleNav('department-contacts');$('#app').innerHTML='<p class="loading">正在加载部门电话…</p>';try{const data=await catalogData();if(seq!==ScoreState.sequence)return;$('#app').innerHTML=`${moduleBack()}<h1 class="portal-title">行政职能部门联系电话</h1><input class="score-search" id="department-query" aria-label="搜索部门或业务" placeholder="输入部门或业务，如教务、招生、户籍"><div id="department-results"></div>`;renderDepartments(data,'');window.scrollTo(0,0);}catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<p class="empty">${esc(e.message)}<button class="btn" data-module="department-contacts">重新加载</button></p>`;}}
function renderDepartments(data,q){
 const rows=data.departments.filter(d=>[d.name,...d.phones.map(p=>p.label)].join(' ').includes(q.trim()));
 const counts=[...new Set(rows.map(d=>d.phones.length))].sort((a,b)=>(a||Infinity)-(b||Infinity));
 $('#department-results').innerHTML=counts.map(count=>{
  const group=rows.filter(d=>d.phones.length===count);
  return `<div class="college-directory department-group ${group.length===1?'contact-solo':''}" data-size="${group.length}" role="group" aria-label="${count?count+'个联系电话的部门':'暂无已核实电话的部门'}">${group.map(d=>`<section class="college-contact"><header><strong>${esc(d.name)}</strong><a href="${esc(d.source)}" target="_blank" rel="noopener">${esc(d.sourceLabel||'官网来源')} ↗</a></header>${count?contactPhonesMarkup(d.phones,d.name):'<p class="score-count">暂未核实公开电话</p><a class="department-help" href="tel:07567626292">联系校办咨询：0756-7626292</a>'}</section>`).join('')}</div>`;
 }).join('')||'<p class="empty">未找到匹配部门</p>';
}

async function showInnovation(){ScoreState.module='catalog';const seq=++ScoreState.sequence;searchSeq++;moduleNav('catalog');CatalogState.origin='innovation';CatalogState.detail='innovation';$('#app').innerHTML='<p class="loading">正在加载创新班…</p>';try{const data=await catalogData();if(seq!==ScoreState.sequence)return;$('#app').innerHTML=`<div class="catalog-back"><button class="back-nav" data-module="catalog">← 返回专业列表</button><button class="back-nav" data-module="home">返回首页</button></div><h1 class="portal-title">创新特色班 · 2026年</h1>${catalogTabs('innovation')}<div class="innovation-links"><a class="btn soft" href="${esc(data.innovation.article)}" target="_blank" rel="noopener">学校推文 ↗</a><a class="btn soft" href="${esc(data.innovation.image)}" target="_blank" rel="noopener">查看原始一览表 ↗</a></div><input id="innovation-query" class="score-search" aria-label="搜索创新班或专业" placeholder="输入班级、专业或学院"><div id="innovation-results"></div>`;renderInnovation(data,'');window.scrollTo(0,0);}catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<p class="empty">${esc(e.message)}<button class="btn" data-innovation-list>重新加载</button></p>`;}}
function renderInnovation(data,q){const rows=data.innovation.records.filter(r=>[r.name,r.major,r.college].some(v=>v.toLowerCase().includes(q.trim().toLowerCase())));$('#innovation-results').innerHTML=`<p class="score-count">${rows.length}个班 · 点击查看对应专业培养介绍</p><div class="college-profile-grid">${rows.map(r=>`<button class="catalog-card innovation-card" data-major-name="${esc(r.major)}"><small>第${r.number}项 · ${esc(r.college)}</small><b>${esc(r.name)}</b><span>${esc(r.major)}</span><span class="catalog-open">培养介绍 ›</span></button>`).join('')||'<p class="empty">未找到匹配班级</p>'}</div>`;}
document.addEventListener('click',e=>{const college=e.target.closest('[data-college-profile]');if(college){showColleges(college.dataset.collegeProfile);return;}if(e.target.closest('[data-innovation-list]'))showInnovation();});
document.addEventListener('input',async e=>{if(!['department-query','innovation-query'].includes(e.target.id))return;const seq=ScoreState.sequence,data=await catalogData();if(seq!==ScoreState.sequence)return;if(e.target.id==='department-query'&&$('#department-results'))renderDepartments(data,e.target.value);if(e.target.id==='innovation-query'&&$('#innovation-results'))renderInnovation(data,e.target.value);});

async function showPolicies(id='scholarship'){ScoreState.module='policies';const seq=++ScoreState.sequence;searchSeq++;moduleNav('policies');$('#app').innerHTML='<p class="loading">正在加载招生政策…</p>';try{const data=await catalogData();if(seq!==ScoreState.sequence)return;const p=data.policies.find(x=>x.id===id);if(!p)throw Error('未找到政策');$('#app').innerHTML=`${moduleBack()}<h1 class="portal-title">招生政策 · 2026级</h1><p class="policy-year-note">以下供2026级新生参考；2027级及以后，请以学校当年公布的政策和办理通知为准。</p><div class="policy-tabs">${data.policies.map(x=>`<button class="${x.id===id?'active':''}" data-policy="${x.id}" aria-pressed="${x.id===id}">${esc(x.name)}</button>`).join('')}</div><article class="policy-detail"><h2>${esc(p.name)}</h2><strong class="policy-highlight">${esc(p.headline)}</strong><p class="score-count">${esc(p.scope)}</p>${p.sections.map(([title,text])=>`<section><h3>${esc(title)}</h3><p>${esc(text)}</p></section>`).join('')}${p.contact?`<a class="policy-contact" href="tel:${esc(p.contact.number.replace(/[^0-9+]/g,''))}">${esc(p.contact.label)} · ${esc(p.contact.number)}</a>`:''}<a href="${esc(p.source)}" target="_blank" rel="noopener">查看学校政策原文 ↗</a></article>`;window.scrollTo(0,0);}catch(e){if(seq===ScoreState.sequence)$('#app').innerHTML=`<p class="empty">${esc(e.message)}<button class="btn" data-module="policies">重新加载</button></p>`;}}
