 async function open(k){kind=k;view='list';const seq=++generation,route=ScoreState.sequence;try{data=await resource('data.json');if(route!==ScoreState.sequence||seq!==generation)return;const id=pendingId;pendingId='';if(id){const r=getRecord(id);if(r){kind=r.year===2027?'transfer-plan':'transfer-score';ScoreState.module=kind;moduleNav(kind);if(r.batch)state().batch=r.batch;}detail(id);}else renderList();window.scrollTo(0,0);}catch(e){if(route===ScoreState.sequence&&seq===generation)$('#app').innerHTML=`<section class="transfer"><p class="empty">${esc(e.message)}</p><button class="btn" data-module="${k}">重新加载</button></section>`;}}
