 document.addEventListener('input',e=>{if(e.target.id==='tr-search'){state().query=e.target.value;state().exact='';state().limit=12;renderResults();}});
 document.addEventListener('change',e=>{const k={'tr-exam':'exam','tr-category':'category','tr-sort':'sort'}[e.target.id];if(k){state()[k]=e.target.value;state().limit=12;renderResults();}});
