'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = v => Number(v).toLocaleString('zh-CN');
const S = {user:null,meta:null,tab:'query',adminTab:'import',school:null,summary:null,search:'',reviewPage:1,reviewKind:'',ticket:null,inspection:null,selectedTarget:null};
let searchSeq=0,toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function fetchReady(url,options={},timeout=20000){
 if(typeof url==="string"&&url.startsWith("/api/"))return mirrorRequest(url,options);
 const controller=new AbortController();let timer;
 const task=(async()=>{const r=await fetch(url,{...options,signal:controller.signal});const body=await r.arrayBuffer();return new Response(body,{status:r.status,statusText:r.statusText,headers:r.headers});})();
 const deadline=new Promise((_,reject)=>{timer=setTimeout(()=>{reject(new Error('网络加载超时，请点击重新加载；也可切换手机热点后重试。'));controller.abort();},timeout);});
 try{return await Promise.race([task,deadline]);}finally{clearTimeout(timer);}
}
async function apiRaw(path,options={}){
  const init={credentials:'same-origin',...options,headers:{'X-Requested-With':'admissions-local',...(options.headers||{})}};
  if(options.body && !(options.body instanceof FormData) && typeof options.body!=='string'){init.body=JSON.stringify(options.body);init.headers['Content-Type']='application/json';}
  const r=await fetchReady(path,init);
  if(!r.ok){let d;try{d=await r.json();}catch{d={detail:'请求没有完成，请检查网络后重试。'};}
    if(r.status===401 && !/login|me/.test(path)){S.user=null;await showLogin(false);}
    throw new Error(typeof d.detail==='string'?d.detail:'填写内容不完整或格式不正确，请检查。');}
  return options.blob?r.blob():r.json();
}
// Short-lived, bounded in-memory cache; writes invalidate all cached reads.
const queryCache=new Map();
function api(path,options={}){
 const method=(options.method||'GET').toUpperCase();
 if(method!=='GET')queryCache.clear();
 const cacheable=method==='GET'&&!options.blob&&/^\/api\/(regions(?:\?|$)|schools(?:\?|$)|schools\/[^/]+\/summary(?:\?|$))/.test(path);
 if(!cacheable)return apiRaw(path,options);
 const key=(S.meta?.version?.id??'')+'|'+path,now=Date.now(),cached=queryCache.get(key);
 if(cached&&cached.expires>now)return cached.promise;
 const entry={expires:now+30000,promise:null};
 entry.promise=readQuery(path,options).catch(error=>{if(queryCache.get(key)===entry)queryCache.delete(key);throw error;});
 queryCache.set(key,entry);if(queryCache.size>100)queryCache.delete(queryCache.keys().next().value);
 return entry.promise;
}
async function readQuery(path,options){
 const match=path.match(/^\/api\/schools\/([a-f0-9]+)\/summary\?(.*)$/);
 if(match&&S.user?.role==='public'){
  if(Date.now()-(S.metaValidatedAt||0)>30000)await refreshMeta();
  const params=new URLSearchParams(match[2]),v=S.meta?.version;
  if(S.meta.snapshot_token&&Number(params.get('start'))===v.default_start&&Number(params.get('end'))===v.default_end&&!params.get('major')){
   try{const response=await fetchReady(`/zcst-admissions-query/summaries/${encodeURIComponent(S.meta.snapshot_token)}/${match[1]}.json`);if(response.ok){const result=await response.json();if(result.version===v.id&&result.school.id===match[1])return result;}}catch{}
  }
 }
 return apiRaw(path,options);
}
function schoolSummaryPath(id,start,end,major=''){const v=S.meta.version;return `/api/schools/${encodeURIComponent(id)}/summary?`+new URLSearchParams({start:start??v.default_start,end:end??v.default_end,major});}
const post=(path,body)=>api(path,{method:'POST',body});
function setAccount(){if(S.user?.role==='public'){$('#account').innerHTML='<span class="status neutral">免登录查询</span><button class="link" data-action="admin-login">管理入口</button>';return;} $('#account').innerHTML=S.user?`<div class="account"><span class="user-label">${esc(S.user.username)} <small>${S.user.role==='admin'?'管理员':'查询人员'}</small></span><button class="link" data-action="password">修改密码</button><button class="btn small" data-action="logout">退出</button></div>`:'<span class="status neutral">内部查询工具</span>'; }
function nav(){return `<nav class="nav" aria-label="主要功能"><button data-action="nav" data-tab="query" class="${S.tab==='query'?'active':''}">学校查询</button>${S.user.role==='admin'?`<button data-action="nav" data-tab="admin" class="${S.tab==='admin'?'active':''}">数据管理</button>`:''}</nav>`;}
function versionLine(){const v=S.meta.version;return v?`<div class="meta-line"><span>默认查询 ${v.default_start}—${v.default_end}级</span><span>数据版本 V${v.id}</span><span>已导入 ${fmt(v.records)} 条明细（${v.years.length}个入学年级）</span></div>`:'<p class="muted">尚未导入录取数据</p>';}
