async function showLogin(setup){setAccount();$('#app').innerHTML=`<div class="login-layout"><section class="login-intro"><div class="eyebrow">ADMISSIONS · ZCST</div><h1>生源中学录取情况<br>随时查询，清楚汇报</h1><p>从一所中学开始，查看历年录取人数、专业分布与学生名单。</p><div class="login-steps"><div><b>01</b><span>搜索生源中学</span></div><div><b>02</b><span>查看年级与专业</span></div><div><b>03</b><span>复制汇报或导出</span></div></div></section><section class="panel login-box"><h2>${setup?'设置管理员账号':'管理员登录'}</h2><p>${setup?'首次使用，请设置您自己的账号和密码。':'普通查询无需登录；此入口仅供数据管理人员使用。'}</p><form id="login-form" data-setup="${setup}"><div class="field"><label for="username">账号</label><input id="username" name="username" autocomplete="username" minlength="2" maxlength="40" required placeholder="请输入账号"></div><div class="field"><label for="password">密码${setup?'（至少8位）':''}</label><input id="password" name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="${setup?8:1}" maxlength="128" required placeholder="请输入密码"></div><div class="form-error" id="login-error" aria-live="polite"></div><button class="btn primary" type="submit">${setup?'创建账号并进入':'登录'}</button></form><small><button type="button" class="link" data-action="reload">返回免登录查询</button></small></section></div>`;}
function cards(list){return list.map(s=>`<button class="school-card school-result-card" data-action="school" data-id="${esc(s.id)}"><span class="school-card-count"><strong>${s.period_total===undefined?'—':fmt(s.period_total)}</strong><span>人 <span aria-hidden="true">›</span></span></span><span class="school-card-info"><b>${esc(s.name)}</b><small>${esc(s.city||'城市待核对')} · ${esc(s.district||'区县未填写')}</small></span></button>`).join('');}
async function showSchoolSearch(){S.tab='query';S.school=null;S.summary=null;$('#app').innerHTML=nav()+`<section class="hero"><div class="eyebrow">学校查询</div><h1>查一所中学，看清历年录取</h1><p>输入学校名称，即可查看五年总数、各年专业和学生名单。</p></section><form id="search-form" class="search-shell"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="7.5"></circle><path d="m16.5 16.5 4.2 4.2"></path></svg><input id="school-search" aria-label="中学名称" value="${esc(S.search)}" placeholder="输入中学名称，如“东华”" autocomplete="off"><button class="btn primary">查询</button></form>${versionLine()}<div class="section-heading"><h3 id="results-title">选择一所学校</h3><span class="result-count" id="results-count"></span></div><div id="school-results" class="school-grid"></div><div class="notice">学校简称、曾用名和地区信息仍需核对，请结合完整校名及城市选择。</div>`;await searchSchools(S.search);window.scrollTo(0,0);}
async function searchSchools(q){q=q.trim();S.search=q;const searching=Boolean(q);$('#region-browser')?.classList.toggle('hidden',searching);$('#home-total')?.classList.toggle('hidden',searching);$('#search-return')?.classList.toggle('hidden',!searching||Boolean(S.regionCity));const heading=$('.compact-hero h1');if(heading)heading.textContent=searching?'生源中学录取查询':S.regionCity?S.regionCity+'录取情况':'生源中学录取查询';if(!searching&&$('#region-browser')){searchSeq++;$('#search-heading')?.classList.add('hidden');$('#school-results').innerHTML='';return;}$('#search-heading')?.classList.remove('hidden');const seq=++searchSeq;const r=await api('/api/schools?'+new URLSearchParams({q,start:S.regionStart??S.meta.version.default_start,end:S.regionEnd??S.meta.version.default_end}));if(seq!==searchSeq||!$('#school-results'))return;$('#results-title').textContent=q?'搜索结果':'已导入的学校';$('#results-count').textContent=r.schools.length?`${S.regionStart??S.meta.version.default_start}—${S.regionEnd??S.meta.version.default_end}级 · ${r.schools.length}所`:'暂无匹配';for(const school of r.schools.slice(0,3))api(schoolSummaryPath(school.id,S.regionStart,S.regionEnd)).catch(()=>{});if(r.schools.length)letterIndex().catch(()=>{});$('#school-results').innerHTML=r.schools.length?cards(r.schools):`<div class="empty"><b>未找到匹配学校</b><p>试试学校名称中的几个字，或核对学校全称。</p></div>`;}
function yearOptions(value){const years=[...new Set((S.meta.version?.years||[]).map(y=>Number(y.year)))].sort((a,b)=>a-b);return years.map(y=>`<option value="${y}" ${y===Number(value)?'selected':''}>${y}级</option>`).join('');}
async function showSchool(id,start,end,major=''){const route=ScoreState.sequence;if(!S.meta.version)return;S.tab='query';const v=S.meta.version;start=Number(start??v.default_start);end=Number(end??v.default_end);const r=await api(schoolSummaryPath(id,start,end,major));if(route!==ScoreState.sequence)return;S.school=r.school;S.summary=r;const s=r.school;const displayNotices=r.notices.filter(n=>!n.includes('待人工核对')&&!n.includes('校名或地区核对提示'));
  $('#app').innerHTML=nav()+`${backButton("back",S.search?"返回搜索结果":S.regionCity?"返回"+S.regionCity+"中学":"返回城市总览")}<div class="detail-head"><div><div class="eyebrow">学校录取档案</div><h2>${esc(s.name)}</h2><div class="location">${esc(s.city||'城市待核对')} · ${esc(s.district||'区县未填写')}</div></div></div><div class="meta-line"><span>入学年级 ${start}—${end}级</span><span>数据版本 V${r.version}</span></div><div class="summary-grid"><div class="total-card"><span class="label">${end-start+1}个入学年级 · ${major?esc(major):'全部专业'}</span><div class="total-number">${fmt(r.total)}<small>人</small></div><span class="foot">所选范围内的已导入录取明细</span></div><div class="panel year-overview"><h3>各年录取人数</h3><div class="annual-grid">${r.annual.map(y=>`<div class="annual-item"><span>${y.year}级</span><strong class="${y.count===null?'missing':''}">${y.count===null?'未导入':fmt(y.count)}</strong>${y.status==='部分名单'?'<small>部分名单</small>':''}</div>`).join('')}</div></div></div><div id="school-letter"></div>${displayNotices.length?`<div class="notice">${displayNotices.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:''}<div class="section-heading"><h3>按年级查看专业和名单</h3><p>点击年级展开</p></div><section>${[...r.annual].reverse().map(y=>`<details class="year-block" data-year="${y.year}"><summary><span><b>${y.year}级</b>　<span class="muted">${y.count===null?'数据未导入':y.count+'人 · '+y.majors.length+'个专业'}</span></span><span class="caret">⌄</span></summary><div class="year-body">${y.count?`<div class="chips"><button class="chip selected" data-action="roster" data-year="${y.year}" data-major="${esc(major)}">${major?esc(major):'全部专业'}<b>${y.count}</b></button>${y.majors.filter(m=>m.major!==major).map(m=>`<button class="chip" data-action="roster" data-year="${y.year}" data-major="${esc(m.major)}">${esc(m.major)}<b>${m.count}</b></button>`).join('')}</div><div id="roster-${y.year}"><p class="muted pad-top">正在加载名单…</p></div>`:`<p class="muted">${y.count===null?'该入学年级的数据尚未导入。':y.status==='完整名单'?'当前筛选下，该校本年级录取为0人。':'当前部分名单中没有符合筛选条件的记录。'}</p>`}</div></details>`).join('')}</section>${S.user.role==='admin'?`<div class="review-tools actions"><button class="btn small" data-action="aliases">管理简称与曾用名</button><button class="btn small" data-action="merge">合并同校记录</button><button class="btn small" data-action="reviewed">${r.status==='已核对'?'恢复为待核对':'标记该校已核对'}</button></div>`:''}`;
  const head=$('.detail-head'),heading=$('h2',head),location=$('.location',head),meta=$('.meta-line');
  const sub=document.createElement('div');sub.className='school-subline';sub.append(location,meta);head.replaceChildren(heading,sub);
  loadLetterCard(id);
 window.scrollTo(0,0);
}
async function roster(year,major,page=1){const query=new URLSearchParams({start:year,end:year,major,page,version:S.summary.version});const box=$('#roster-'+year);if(!box)return;const request=String(Number(box.dataset.request||0)+1);box.dataset.request=request;const r=await api(`/api/schools/${S.school.id}/students?${query}`);if($('#roster-'+year)!==box||box.dataset.request!==request)return;box.dataset.loaded='true';box.innerHTML=`<div class="roster-title"><span>共${r.total}人</span><button class="roster-export" data-action="export" data-year="${year}" data-major="${esc(major)}">导出名单</button></div><div class="roster-list">${r.rows.map(s=>`<div class="student"><b>${esc(s.name)}</b><small>${esc(s.major)}</small></div>`).join('')}</div>${r.total>r.size?`<div class="pagination"><button class="btn small" data-action="roster" data-year="${year}" data-major="${esc(major)}" data-page="${page-1}" ${page===1?'disabled':''}>上一页</button><span>${page} / ${Math.ceil(r.total/r.size)}</span><button class="btn small" data-action="roster" data-year="${year}" data-major="${esc(major)}" data-page="${page+1}" ${page*r.size>=r.total?'disabled':''}>下一页</button></div>`:''}`;box.closest('details').querySelectorAll('.chip').forEach(b=>b.classList.toggle('selected',b.dataset.major===major));}
async function downloadFile(path,fallback){const r=await fetchReady(path,{credentials:'same-origin'});if(!r.ok){let t;try{t=await r.json();}catch{t={};}throw new Error(t.detail||'导出失败，请重试。');}let blob=await r.blob();let filename=fallback;const h=r.headers.get('content-disposition')||'';const m=h.match(/filename\*=UTF-8''(.+)/);if(m)filename=decodeURIComponent(m[1]);
  if(r.headers.get('content-type')?.includes('application/json')){const d=JSON.parse(await blob.text());const exporter=await import('/zcst-admissions-query/exporter.js');blob=exporter.makeWorkbook(d);filename=d.filename||fallback;}
  const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast(/MicroMessenger/i.test(navigator.userAgent)?'已请求导出。微信若未下载，请用右上角菜单在浏览器中打开。':'已生成导出文件');}
function modal(html){$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function closeModal(){$('#dialog').close();}
async function copyReport(){try{await navigator.clipboard.writeText(S.summary.report);toast('汇报文字已复制');}catch{modal(`<h2>汇报文字</h2><p class="muted">长按或全选下方文字后复制。</p><textarea id="report-text" readonly>${esc(S.summary.report)}</textarea><div class="actions"><button class="btn" data-action="close">关闭</button></div>`);$('#report-text').select();}}
function help(){S.tab='help';$('#app').innerHTML=nav()+`<section class="panel help"><div class="eyebrow">使用说明</div><h2>从校名到名单，只需几步</h2><h3>1. 搜索学校</h3><p>输入学校全称或几个关键字，再结合城市、区县选择学校。同名学校不会仅凭名称自动合并。</p><h3>2. 看人数和专业</h3><p>默认查询最新连续五个入学年级。可以调整起止年级或专业，展开某一年后点击专业查看姓名。“级”表示入学年级，不表示学生当前在读年级。</p><h3>3. 汇报和导出</h3><p>“复制汇报”包含当前范围内的逐年人数及核对提示。“导出Excel”包含年度统计、专业统计和学生名单。年级内部的“导出此名单”只导出当前年级和专业。</p><h3>4. 手机微信使用</h3><p>线上版使用固定HTTPS网址，电脑关机后仍能访问。打开即可查询、复制和导出，无需账号密码；如果微信限制文件下载，请从右上角菜单选择在浏览器中打开后导出。</p><h3>5. 管理数据</h3><p>数据维护人员从右上角“管理入口”登录，在“数据管理”上传Excel、对应字段、查看预览，再确认替换所选年份。请勾选完整年度名单的真实情况；新版本出错时可回退。缺失年份显示“未导入”，部分名单不作为全年总人数。</p><h3>6. 核对状态与版本</h3><p>学校总数来自学生明细。汇总表仅用于比对；校名错误、地区冲突及无法归属的记录进入核对清单。人工合并或修订会生成新数据版本；涉及原汇总表的核对事项需重新人工对照。别名和用户账号独立管理，回退数据版本不会删除账号及别名。</p><h3>7. 免费运行范围</h3><p>线上服务使用Cloudflare免费套餐，不接付费AI接口。免费额度达到上限时可能暂停访问，恢复额度后再试；不要在托管平台主动升级付费套餐。实际网络可达性以您的手机测试为准。</p></section>`;}
async function showAdmin(tab=S.adminTab){S.tab='admin';S.adminTab=tab;$('#app').innerHTML=nav()+`<div class="hero"><div class="eyebrow">管理员工作台</div><h1>数据管理</h1><p>先预览、再启用，每次更新保留可回退的数据版本。</p></div>${versionLine()}<div class="admin-tabs">${[['import','导入Excel'],['review','核对清单'],['versions','版本记录'],['users','账号管理']].map(([id,label])=>`<button class="btn ${id===tab?'active':''}" data-action="admin-tab" data-tab="${id}">${label}</button>`).join('')}</div><div id="admin-content"></div>`;
  if(tab==='import')importForm();if(tab==='review')await showReview();if(tab==='versions')await showVersions();if(tab==='users')await showUsers();}
function importForm(){$('#admin-content').innerHTML=`<section class="panel"><h3>1. 上传录取明细</h3><p class="muted pad-top">支持.xlsx文件，最大25MB。每次按选择的入学年份整体替换，不重复追加。</p><form id="upload-form" class="row pad-top"><input id="xlsx-file" type="file" accept=".xlsx" required aria-label="选择Excel文件"><button class="btn primary">读取工作表</button></form><div id="import-progress" class="progress-line" aria-live="polite"></div></section><div id="mapping-area"></div><div id="preview-area"></div>`;}
const fieldNames={year:'入学年级 *',name:'学生姓名 *',major:'录取专业 *',raw_school:'系统导出校名',checked_school:'核对后校名',city:'城市',district:'区县',id:'身份证号（仅去重）',candidate:'考生号（仅去重）'};
function mappingForm(){const sheets=S.inspection.sheets;const selected=sheets.find(s=>s.mapping.year!==undefined&&s.mapping.name!==undefined)||sheets[0];$('#mapping-area').innerHTML=`<section class="panel pad-top"><h3>2. 确认字段对应</h3><div class="field pad-top"><label for="sheet-select">学生明细工作表</label><select id="sheet-select">${sheets.map(s=>`<option value="${esc(s.name)}" ${s===selected?'selected':''}>${esc(s.name)}（约${s.rows}行）</option>`).join('')}</select></div><form id="mapping-form"><div class="mapping" id="field-mapping"></div><button class="btn primary">预览导入结果</button></form></section>`;renderMapping(selected.name);}
function renderMapping(name){const s=S.inspection.sheets.find(x=>x.name===name);$('#field-mapping').innerHTML=Object.entries(fieldNames).map(([key,label])=>`<div class="field"><label for="map-${key}">${label}</label><select id="map-${key}"><option value="">不使用此字段</option>${s.headers.map((h,i)=>`<option value="${i}" ${s.mapping[key]===i?'selected':''}>${i+1}. ${esc(h||'空表头')}</option>`).join('')}</select></div>`).join('');$('#preview-area').innerHTML='';}
function renderPreview(r){S.preview=r;$('#preview-area').innerHTML=`<section class="panel pad-top"><h3>3. 预览并选择更新年份</h3><p class="muted pad-top">可导入 ${fmt(Object.values(r.years).reduce((a,b)=>a+b,0))} 条；校名或地区待核对 ${fmt(r.flagged)} 条；学校未归属 ${r.unassigned} 条；完全重复记录已合并 ${r.duplicates} 条。</p>${r.errors.length?`<div class="notice"><b>有 ${r.errors.length} 处问题，暂不能启用</b>${r.errors.slice(0,12).map(e=>`<p>第${e.row}行：${esc(e.reason)}</p>`).join('')}</div>`:''}<form id="commit-form"><div class="checks">${Object.entries(r.years).map(([y,n])=>`<label class="check"><input type="checkbox" name="years" value="${y}" checked>${y}级 · ${fmt(n)}人</label>`).join('')}</div><label class="check"><input type="checkbox" id="complete-data" checked>所选年份包含完整的年度录取名单</label><p class="muted pad-top">确认后，以上年份的旧明细将被整体替换，其余年份保留。校名映射、学校归属修订及已核对状态需随新数据重新核验。</p><button class="btn primary pad-top" ${r.errors.length?'disabled':''}>确认更新并启用</button></form></section>`;}
async function showReview(){const r=await api('/api/admin/review?'+new URLSearchParams({kind:S.reviewKind,page:S.reviewPage}));S.reviewItems=r.items;$('#admin-content').innerHTML=`<div class="row"><select id="review-kind" aria-label="核对类型">${[['','全部核对事项'],['未归属','学校未归属'],['校名与地区','校名与地区'],['人数比对','人数比对']].map(([v,t])=>`<option value="${v}" ${S.reviewKind===v?'selected':''}>${t}</option>`).join('')}</select><span class="muted">共 ${fmt(r.total)} 项</span><button class="btn small" data-action="review-export">导出核对清单</button></div><div class="admin-stack pad-top">${r.items.map((x,i)=>`<article class="review-card"><div class="review-head"><h3>${esc(x.school)} <small>${x.year}级</small></h3><span class="status neutral">${esc(x.kind)}</span></div><p>${esc(x.city)} ${esc(x.district||'')}</p><p>${esc(x.detail)}</p>${x.raw_school||x.checked_school?`<p>原始校名：${esc(x.raw_school||'未填写')}<br>核对后校名：${esc(x.checked_school||'未填写')}</p>`:''}<div class="source">${esc(x.source_file)} · ${esc(x.source_sheet)} ${x.source_row?'· 第'+x.source_row+'行':''}</div><div class="actions pad-top">${x.row_key?`<button class="btn small" data-action="correct" data-index="${i}">修订学校归属</button>`:''}${x.school_id?`<button class="btn small" data-action="school" data-id="${esc(x.school_id)}">查看该校</button>`:''}</div></article>`).join('')||'<div class="empty">该分类没有待处理事项。</div>'}</div><div class="pagination"><button class="btn small" data-action="review-page" data-page="${S.reviewPage-1}" ${S.reviewPage===1?'disabled':''}>上一页</button><span>${S.reviewPage} / ${Math.max(1,Math.ceil(r.total/40))}</span><button class="btn small" data-action="review-page" data-page="${S.reviewPage+1}" ${S.reviewPage*40>=r.total?'disabled':''}>下一页</button></div>`;}
async function showVersions(){const r=await api('/api/admin/versions');$('#admin-content').innerHTML=`<section class="panel"><h3>数据版本</h3>${r.versions.map(v=>`<div class="version-row"><div><b>V${v.id} · ${esc(v.label)}</b><small>${esc(v.source)}</small><small>${esc(v.note||'')}</small></div>${v.id===r.active?'<span class="status ok">正在使用</span>':`<button class="btn small" data-action="rollback" data-id="${v.id}">启用此版本</button>`}</div>`).join('')}</section>`;}
async function showUsers(){const users=await api('/api/admin/users');$('#admin-content').innerHTML=`<section class="panel"><div class="row"><h3>内部账号</h3><button class="btn small primary" data-action="new-user">新增账号</button></div>${users.map(u=>`<div class="user-row"><div><b>${esc(u.username)}</b><small>${u.role==='admin'?'管理员':'查询人员'} · ${u.enabled?'已启用':'已停用'}</small></div><div class="actions"><button class="btn small" data-action="reset-password" data-id="${u.id}">重设密码</button>${u.id!==S.user.id?`<button class="btn small" data-action="toggle-user" data-id="${u.id}" data-enabled="${u.enabled?0:1}">${u.enabled?'停用':'启用'}</button>`:''}</div></div>`).join('')}</section>`;}
function targetPicker(){return `<div class="field"><label for="target-search">搜索目标学校</label><input id="target-search" placeholder="输入学校名称"></div><div class="dialog-results" id="target-results"></div><div id="target-selected"></div>`;}
async function targetSearch(q){const r=await api('/api/schools?q='+encodeURIComponent(q));if(!$('#target-results'))return;S.targetResults=r.schools;$('#target-results').innerHTML=r.schools.map((s,i)=>`<button class="school-card" data-action="target" data-index="${i}"><span>${esc(s.name)}<small>${esc(s.city)} ${esc(s.district)}</small></span></button>`).join('')||'<p class="muted">未找到，可在下方填写新学校。</p>';}
async function aliasDialog(){const r=await api('/api/admin/aliases/'+S.school.id);modal(`<h2>简称与曾用名</h2><p class="muted">${esc(S.school.name)}</p><div class="stack pad-top">${r.map(a=>`<div class="row"><span>${esc(a.name)}</span><button class="link" data-action="delete-alias" data-id="${a.id}">删除</button></div>`).join('')||'<p class="muted">尚未设置</p>'}</div><form id="alias-form"><div class="field"><label for="alias-name">确认属于该校的简称或曾用名</label><input id="alias-name" maxlength="150" required></div><div class="actions"><button type="button" class="btn" data-action="close">关闭</button><button class="btn primary">保存别名</button></div></form>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='home'){e.preventDefault();}const navigating=['school','region','back','region-home','home','letter-back'].includes(a);if(navigating){b.disabled=true;$('#app').setAttribute('aria-busy','true');document.body.classList.add('page-opening');}try{if(a==='home'){S.regionStart=undefined;S.regionEnd=undefined;await showHome();}
  if(a==='admin-login'){location.href='https://zcst-admissions-query.pages.dev/';return;}if(a==='reload'){await boot();return;}if(a==='close'){closeModal();return;}if(a==='logout'){await post('/api/logout',{});S.user=null;await boot();return;}
  if(a==='nav'){if(b.dataset.tab==='query')await showQuery();if(b.dataset.tab==='admin')await showAdmin();}
  if(a==='back')await showQuery(S.regionCity??null,true);if(a==='school'){document.activeElement?.blur();await showSchool(b.dataset.id,S.regionStart,S.regionEnd);}if(a==='region')await showQuery(b.dataset.city);if(a==='region-home')await showQuery();if(a==='copy')await copyReport();if(a==='city-report')await showCityReport(b.dataset.city);if(a==='report-zoom'){const zoom=$('#report-pages').classList.toggle('zoomed');b.textContent=zoom?'适应屏幕':'放大文字';b.setAttribute('aria-pressed',String(zoom));}if(a==='letter-preview')await showLetter();if(a==='letter-back')await showSchool(S.school.id,S.summary.start,S.summary.end,S.summary.major);if(a==='letter-zoom'){const zoom=$('#letter-canvas').classList.toggle('zoomed');b.textContent=zoom?'适应屏幕':'放大文字';b.setAttribute('aria-pressed',String(zoom));}
  if(a==='roster')await roster(Number(b.dataset.year),b.dataset.major||'',Number(b.dataset.page||1));
  if(a==='export'){b.disabled=true;const y=b.dataset.year;const q=new URLSearchParams({start:y||S.summary.start,end:y||S.summary.end,major:y?b.dataset.major||'':S.summary.major,version:S.summary.version});await downloadFile(`/api/schools/${S.school.id}/export?${q}`,'录取情况.xlsx');}
  if(a==='admin-tab'){S.reviewPage=1;await showAdmin(b.dataset.tab);}if(a==='review-page'){S.reviewPage=Number(b.dataset.page);await showReview();}if(a==='review-export'){b.disabled=true;if(S.meta.runtime==='cloud')await exportCloudReview();else await downloadFile('/api/admin/review/export','核对清单.csv');}
  if(a==='rollback'&&confirm(`确认启用V${b.dataset.id}？当前版本会保留，可再次切换回来。`)){await post('/api/admin/rollback',{version:Number(b.dataset.id),expected_version:S.meta.version.id});await refreshMeta();await showAdmin('versions');toast('数据版本已切换');}
  if(a==='aliases')await aliasDialog();if(a==='delete-alias'){await api('/api/admin/aliases/'+b.dataset.id,{method:'DELETE'});closeModal();await aliasDialog();}
  if(a==='reviewed'){const reviewed=S.summary.status!=='已核对';if(confirm(reviewed?'请确认已核对该校各年的校名、地区和人数差异。标记只适用于当前数据版本。':'将该校恢复为待核对状态？')){await post('/api/admin/reviewed',{school_id:S.school.id,expected_version:S.summary.version,reviewed});await showSchool(S.school.id,S.summary.start,S.summary.end,S.summary.major);}}
  if(a==='target'){S.selectedTarget=S.targetResults[Number(b.dataset.index)];$('#target-selected').innerHTML=`<div class="selected-school pad-top">已选：${esc(S.selectedTarget.name)} · ${esc(S.selectedTarget.city)} ${esc(S.selectedTarget.district)}</div>`;$('#target-results').innerHTML='';}
  if(a==='correct'){S.correction=S.reviewItems[Number(b.dataset.index)];S.selectedTarget=null;modal(`<h2>修订学校归属</h2><p class="muted">${esc(S.correction.source_sheet)} · 第${S.correction.source_row}行 · ${S.correction.year}级</p>${targetPicker()}<details class="pad-top"><summary>目标学校尚未入库，填写新学校</summary><div class="field"><label>学校全称</label><input id="new-school-name"></div><div class="row"><div class="field"><label>城市</label><input id="new-school-city"></div><div class="field"><label>区县</label><input id="new-school-district"></div></div></details><div class="actions"><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="save-correction">确认修订</button></div>`);}
  if(a==='save-correction'){await post('/api/admin/correct',{expected_version:S.meta.version.id,row_key:S.correction.row_key,school_id:S.selectedTarget?.id||'',name:$('#new-school-name').value,city:$('#new-school-city').value,district:$('#new-school-district').value});closeModal();await refreshMeta();await showAdmin('review');toast('已生成学校归属修订版本');}
  if(a==='merge'){S.selectedTarget=null;modal(`<h2>合并同一学校的记录</h2><p class="muted">将“${esc(S.school.name)}”的全部明细归入您选择的目标学校。仅在确认两者为同一学校时操作。</p>${targetPicker()}<div class="actions"><button class="btn" data-action="close">取消</button><button class="btn primary" data-action="save-merge">确认同校并合并</button></div>`);}
  if(a==='save-merge'){if(!S.selectedTarget)throw new Error('请先选择目标学校。');await post('/api/admin/merge',{expected_version:S.summary.version,source:S.school.id,target:S.selectedTarget.id});closeModal();await refreshMeta();await showSchool(S.selectedTarget.id);toast('已生成合并修订版本');}
  if(a==='new-user'){modal(`<h2>新增内部账号</h2><form id="new-user-form"><div class="field"><label>账号</label><input name="username" required minlength="2" maxlength="40" autocomplete="off"></div><div class="field"><label>密码（至少8位）</label><input name="password" type="password" required minlength="8" autocomplete="new-password"></div><div class="field"><label>角色</label><select name="role"><option value="reader">查询人员：查询、复制与导出</option><option value="admin">管理员：同时管理数据和账号</option></select></div><div class="actions"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary">创建账号</button></div></form>`);}
  if(a==='toggle-user'){await api('/api/admin/users/'+b.dataset.id,{method:'PATCH',body:{enabled:b.dataset.enabled==='1'}});await showUsers();}
  if(a==='password'||a==='reset-password'){modal(`<h2>${a==='password'?'修改自己的密码':'重设账号密码'}</h2><form id="password-form" data-id="${b.dataset.id||''}">${a==='password'?'<div class="field"><label>当前密码</label><input name="old_password" type="password" autocomplete="current-password" required></div>':''}<div class="field"><label>新密码（至少8位）</label><input name="password" type="password" autocomplete="new-password" minlength="8" required></div><div class="actions"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary">保存新密码</button></div></form>`);}
}catch(err){toast(err.message);}finally{b.disabled=false;if(navigating){$('#app').removeAttribute('aria-busy');document.body.classList.remove('page-opening');}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=$('button[type="submit"],button:not([type])',f);if(b)b.disabled=true;try{
  if(f.id==='login-form'){const body=Object.fromEntries(new FormData(f));await post(f.dataset.setup==='true'?'/api/setup':'/api/login',body);$('#password').value='';await refreshMeta();await showQuery();}
  if(f.id==='region-range'){S.regionStart=Number($('#region-start').value);S.regionEnd=Number($('#region-end').value);await showQuery(S.regionCity??null);}
  if(f.id==='search-form')await searchSchools($('#school-search').value.trim());
  if(f.id==='filters')await showSchool(S.school.id,Number($('#from-year').value),Number($('#to-year').value),$('#major-filter').value);
  if(f.id==='upload-form'){$('#import-progress').textContent='正在读取Excel…';const file=$('#xlsx-file').files[0];if(!file)throw new Error('请选择Excel文件。');if(S.meta.runtime==='cloud'){S.importer=await import('/importer.js');S.inspection=await S.importer.inspect(file);}else{const form=new FormData();form.append('file',file);S.inspection=await api('/api/admin/import/inspect',{method:'POST',body:form});}S.ticket=S.inspection.ticket;mappingForm();$('#import-progress').textContent='工作表已读取，请确认字段。';}
  if(f.id==='mapping-form'){const mapping={};for(const k of Object.keys(fieldNames)){const val=$('#map-'+k).value;mapping[k]=val===''?null:Number(val);}$('#import-progress').textContent='正在校验字段、重复记录和学校归属…';let r;if(S.meta.runtime==='cloud'){const salt=await api('/api/admin/import-salt');r=await S.importer.preview($('#sheet-select').value,mapping,salt.salt);}else r=await post('/api/admin/import/preview',{ticket:S.ticket,sheet:$('#sheet-select').value,mapping});renderPreview(r);$('#import-progress').textContent='预览完成，请查看下方结果。';}
  if(f.id==='commit-form'){const years=[...f.querySelectorAll('[name="years"]:checked')].map(x=>Number(x.value));if(!years.length)throw new Error('至少选择一个年份。');if(!confirm(`确认整体替换${years.join('、')}级的明细并启用新版本？`))return;const complete=$('#complete-data').checked;if(S.meta.runtime==='cloud'){await S.importer.commit({years,complete,expected_version:S.meta.version?.id??null,api,progress:t=>{$('#import-progress').textContent=t;}});}else await post('/api/admin/import/commit',{ticket:S.ticket,years,complete});await refreshMeta();await showAdmin('versions');toast('新数据已启用');}
  if(f.id==='alias-form'){await post('/api/admin/aliases',{school_id:S.school.id,name:$('#alias-name').value});closeModal();await aliasDialog();}
  if(f.id==='new-user-form'){await post('/api/admin/users',Object.fromEntries(new FormData(f)));closeModal();await showUsers();toast('账号已创建');}
  if(f.id==='password-form'){const data=Object.fromEntries(new FormData(f));if(f.dataset.id){await api('/api/admin/users/'+f.dataset.id,{method:'PATCH',body:{password:data.password}});closeModal();if(Number(f.dataset.id)===S.user.id){S.user=null;await showLogin(false);}else await showUsers();}else{await post('/api/password',data);closeModal();S.user=null;await showLogin(false);}toast('密码已更新，请使用新密码登录');}
}catch(err){if(f.id==='login-form')$('#login-error').textContent=err.message;else toast(err.message);if($('#import-progress')&&/upload|mapping|commit/.test(f.id))$('#import-progress').textContent=err.message;}finally{if(b)b.disabled=false;}});
let debounce;document.addEventListener('input',e=>{if(!['school-search','target-search'].includes(e.target.id))return;clearTimeout(debounce);const id=e.target.id,q=e.target.value;debounce=setTimeout(()=>{(id==='school-search'?searchSchools(q):targetSearch(q)).catch(e=>toast(e.message));},280);});
document.addEventListener('toggle',e=>{const detail=e.target;if(!detail.matches?.('.year-block')||!detail.open)return;const year=Number(detail.dataset.year),box=$('#roster-'+year);if(box&&!box.dataset.loaded)roster(year,$('.year-major',detail)?.value||'').catch(error=>{box.textContent='名单加载失败，请重新展开重试。';toast(error.message);});},true);
document.addEventListener('change',e=>{if(e.target.matches('.year-major'))roster(Number(e.target.dataset.year),e.target.value).catch(error=>toast(error.message));});
document.addEventListener('change',async e=>{
 const id=e.target.id,regional=['region-start','region-end'].includes(id),school=['from-year','to-year','major-filter'].includes(id);
 if(!regional&&!school)return;
 const form=e.target.closest('form'),fields=[...form.querySelectorAll('select')];
 const startInput=$(regional?'#region-start':'#from-year'),endInput=$(regional?'#region-end':'#to-year');
 if(Number(startInput.value)>Number(endInput.value)){if(id==='region-start'||id==='from-year')endInput.value=startInput.value;else startInput.value=endInput.value;}
 const start=Number(startInput.value),end=Number(endInput.value),scrollY=window.scrollY;
 fields.forEach(x=>x.disabled=true);document.body.classList.add('page-opening');
 try{if(regional){S.regionStart=start;S.regionEnd=end;await showQuery(S.regionCity??null);}else await showSchool(S.school.id,start,end,$('#major-filter').value);window.scrollTo(0,scrollY);}
 catch(error){toast(error.message);}
 finally{fields.forEach(x=>x.disabled=false);document.body.classList.remove('page-opening');}
});
document.addEventListener('change',e=>{if(e.target.id==='sheet-select')renderMapping(e.target.value);if(e.target.id==='review-kind'){S.reviewKind=e.target.value;S.reviewPage=1;showReview().catch(e=>toast(e.message));}});
boot();

async function exportCloudReview(){
  const version=S.meta.version.id,items=[];let page=1,total=0;
  do{const r=await api('/api/admin/review?'+new URLSearchParams({page,limit:400}));if(r.version!==version)throw new Error('数据版本已变化，请重新导出。');items.push(...r.items);total=r.total;page++;toast(`正在生成核对清单 ${fmt(items.length)}/${fmt(total)}`);}while(items.length<total);
  const rows=[['数据版本','类型','学校','城市','区县','入学年级','核对事项','原始校名','核对后校名','明细人数','汇总人数','来源文件','工作表','原始行号'],...items.map(i=>['V'+version,i.kind,i.school,i.city,i.district,i.year,i.detail,i.raw_school,i.checked_school,i.detail_count,i.summary_count,i.source_file,i.source_sheet,i.source_row])];
  const safe=v=>{let t=String(v??'');if(/^[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};
  const blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`校名与人数核对清单_V${version}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('核对清单已生成');
}


async function showQuery(city=null,restoreSearch=false){const route=ScoreState.sequence;
 if(!restoreSearch)S.search='';searchSeq++;
 S.tab='query';S.school=null;S.summary=null;S.regionCity=city;
 const v=S.meta.version;if(!v){await showSchoolSearch();return;}
 const start=S.regionStart??v.default_start,end=S.regionEnd??v.default_end;
 const q=new URLSearchParams({start,end});if(city!==null)q.set('city',city);
 const r=await api('/api/regions?'+q);S.regionStart=r.start;S.regionEnd=r.end;
 const report=city!==null?await cityReportIndex().then(x=>x[city]).catch(()=>null):null;
 if(route!==ScoreState.sequence)return;
 const selected=r.regions.find(x=>x.city===city),max=Math.max(1,...r.regions.map(x=>x.total));
 const annual=x=>`<div class="annual-grid">${x.annual.map(y=>`<div class="annual-item"><span>${y.year}级</span><strong class="${y.count===null?'missing':''}">${y.count===null?'未导入':fmt(y.count)}</strong>${y.status==='部分名单'?'<small>部分名单</small>':''}</div>`).join('')}</div>`;
 const missing=r.regions[0]?.annual.filter(y=>y.count===null).map(y=>y.year)||[],partial=r.regions[0]?.annual.filter(y=>y.status==='部分名单').map(y=>y.year)||[];
 $('#app').innerHTML=nav()+`${city!==null?backButton('region-home','返回城市总览'):''}<section class="hero compact-hero"><h1>${city!==null?esc(city)+'录取情况':'生源中学录取查询'}</h1>${city===null?`<div id="home-total" class="home-total"><span>广东21市合计</span><div><strong>${fmt(r.total)}</strong><small>人</small></div><span>${start}—${end}级</span></div>`:''}</section><section id="region-search"><div id="search-return" class="hidden">${backButton("region-home","返回城市总览")}</div><form id="search-form" class="search-shell"><input id="school-search" aria-label="中学名称" placeholder="直接输入中学名称，如“东华”" value=""><button class="btn primary">查询</button></form><div class="section-heading hidden" id="search-heading"><h3 id="results-title">搜索结果</h3><span id="results-count"></span></div><div id="school-results" class="school-grid"></div></section>
 <div id="region-browser"><form id="region-range" class="filterbar"><div class="field"><label for="region-start">起始年级</label><select id="region-start">${yearOptions(start)}</select></div><div class="field"><label for="region-end">截止年级</label><select id="region-end">${yearOptions(end)}</select></div></form>${city!==null?`<div class="meta-line"><span>${esc(city)}合计 ${fmt(selected?.total??r.total)} 人</span></div>`:''}
 ${missing.length||partial.length?`<div class="notice">${missing.length?esc(missing.join('、'))+'级数据未导入。':''}${partial.length?esc(partial.join('、'))+'级仅有部分名单。':''}合计仅包含已导入记录。</div>`:''}
 ${report?cityReportCard(report):''}
 ${city===null?`<section class="city-visual"><div class="section-heading"><h3>各市录取人数</h3><span class="muted">点击城市查看中学</span></div><div class="city-chart" role="group" aria-label="广东省21个地级市录取人数，按人数从高到低排列">${r.regions.map(x=>`<button class="city-bar" data-action="region" data-city="${esc(x.city)}" aria-label="${esc(x.city)}，${x.total}人，点击查看中学"><span class="city-bar-label"><b>${esc(x.city)}</b><strong>${fmt(x.total)}<span aria-hidden="true"> ›</span></strong></span><svg viewBox="0 0 100 5" preserveAspectRatio="none" aria-hidden="true"><rect width="100" height="5" rx="2" fill="#e9eff8"/><rect width="${(100*x.total/max).toFixed(3)}" height="5" rx="2" fill="#2d67bd"/></svg></button>`).join('')}</div><p class="chart-foot">按生源中学所在城市统计 · 单位：人</p></section>`:selected?`<div class="summary-grid"><div class="total-card"><span class="label">${esc(city)} · ${start}—${end}级</span><div class="total-number">${fmt(selected.total)}<small>人</small></div><span class="foot">${selected.schools}所中学有录取记录</span></div><div class="panel year-overview"><h3>各年录取人数</h3>${annual(selected)}</div></div><div class="section-heading"><h3>${esc(city)}中学</h3><span class="muted">${r.schools.length}所 · 按人数排列</span></div><div class="school-grid">${cards(r.schools)||'<div class="empty">所选年级暂无录取记录。</div>'}</div>`:'<div class="empty">未找到该地区。</div>'}</div>`;
 if(restoreSearch&&S.search){$('#school-search').value=S.search;await searchSchools(S.search);}
 window.scrollTo(0,0);
}

function backButton(action,label){return `<button class="back-nav" data-action="${action}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 5 7 12l7 7M7 12h14"/></svg><span>${esc(label)}</span></button>`;}
async function letterIndex(){if(!S.lettersPromise)S.lettersPromise=fetchReady('/zcst-admissions-query/letters/index.json').then(r=>{if(!r.ok)throw new Error('感谢信索引暂不可用');return r.json();}).catch(e=>{S.lettersPromise=null;throw e;});return S.lettersPromise;}
function letterDownload(x){return `<a class="btn primary" href="${esc(x.pdf)}" download="2026级录取感谢信_${esc(x.title)}.pdf">下载原版PDF</a>`;}
function letterCaution(x){return x.matched?'':`<p class="letter-warning">存档信载${x.count}人，与本次导入数据的名单不完全一致。原信未修改，请核对后使用。</p>`;}
async function loadLetterCard(id){
 try{const x=(await letterIndex())[id];if(S.school?.id!==id||!$('#school-letter'))return;S.letter=x||null;
 if(!x)return;
 $('#school-letter').innerHTML=`<section class="letter-card"><div><span class="attachment-label">学校材料</span><h3>2026级录取感谢信</h3><p>原版PDF · ${x.count}人${x.title!==x.school?' · 原信抬头：'+esc(x.title):''}</p></div><div class="actions"><button class="btn soft" data-action="letter-preview">预览感谢信</button>${letterDownload(x)}</div>${letterCaution(x)}</section>`;
 }catch{if(S.school?.id===id&&$('#school-letter'))$('#school-letter').innerHTML='<p class="muted">感谢信暂时无法加载，请稍后重新打开学校页面。</p>';}
}
async function showLetter(){
 const x=S.letter;if(!x)return;
 $('#app').innerHTML=`${backButton('letter-back','返回学校详情')}<div class="letter-heading"><span class="eyebrow">2026级 · 录取感谢信</span><h2>${esc(x.school)}</h2><p>查看已制作原稿，下载保留原版清晰度。</p></div>${letterCaution(x)}<div class="letter-toolbar">${letterDownload(x)}<button class="btn" data-action="letter-zoom" aria-pressed="false">放大文字</button></div><div class="letter-canvas" id="letter-canvas"><img src="${esc(x.preview)}" alt="${esc(x.title)}2026级录取感谢信预览" width="1132" height="1600"></div><p class="letter-help">点击“放大文字”可放大阅读；如微信拦截PDF下载，可从右上角菜单选择在浏览器打开。</p>`;
 window.scrollTo(0,0);
}

async function cityReportIndex(){if(!S.reportsPromise)S.reportsPromise=fetchReady('/zcst-admissions-query/reports/index.json').then(r=>{if(!r.ok)throw new Error('报告索引加载失败');return r.json();}).catch(e=>{S.reportsPromise=null;throw e;});return S.reportsPromise;}
function cityReportDownload(x){return `<a class="btn primary" href="${esc(x.word)}" download="珠海科技学院近五年在${esc(x.city.slice(0,-1))}招生录取情况.docx">下载Word</a>`;}
function cityReportCard(x){return `<section class="city-report-card"><div><h3>地方招生报告</h3><small>2022—2026年 · ${x.pages}页</small></div><div class="actions"><button class="btn soft" data-action="city-report" data-city="${esc(x.city)}">预览报告</button>${cityReportDownload(x)}</div></section>${x.warning?`<p class="report-note">${esc(x.warning)}</p>`:''}`;}
async function showCityReport(city){const route=ScoreState.sequence;const x=(await cityReportIndex())[city];if(!x||route!==ScoreState.sequence)return;$('#app').innerHTML=`<button class="back-nav" data-action="region" data-city="${esc(city)}">← 返回${esc(city)}</button><div class="report-heading"><h2>${esc(city)}地方招生报告</h2><small>2022—2026年 · 已制作原稿 · ${x.pages}页</small></div>${x.warning?`<p class="report-note">${esc(x.warning)}</p>`:''}<div class="letter-toolbar">${cityReportDownload(x)}<button class="btn" data-action="report-zoom" aria-pressed="false">放大文字</button></div><div class="report-pages" id="report-pages">${x.previews.map((src,i)=>`<figure><figcaption>第${i+1} / ${x.pages}页</figcaption><img src="${esc(src)}" alt="${esc(city)}地方招生报告第${i+1}页" ${i?'loading="lazy"':''}></figure>`).join('')}</div><p class="letter-help">如微信无法下载Word，可通过右上角菜单选择在浏览器打开。</p>`;window.scrollTo(0,0);}
